head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[treeview > P > renderType]<br/>컴포넌트가 렌더링 되는 방식을 설정합니다.",
    "validation" : [
        "미설정 또는 table 설정 시 TreeView 컴포넌트의 최상위 요소는 div 태그로 렌더링되며 'w2treeview' 클래스가 추가됩니다.",
        "미설정 또는 table 설정 시 table 태그를 갖는 div 태그로 트리 아이템들이 정의되며 최초 로딩 시 트리 아이템이 모두 펼쳐져서 표시됩니다.",
        "virtual 설정 시 TreeView 컴포넌트의 최상위 요소는 div 태그로 렌더링되며 'w2treeview_virtual' 클래스가 추가됩니다.",
        "virtual 설정 시 div 태그로 트리 아이템들이 정의되며 최초 로딩 시 showTreeDepth 속성을 설정하지 않으면 트리 아이템이 모두 접혀서 표시됩니다.",
        "렌더링 되는 태그에 따라 'w2treeview', 'w2treeview_virtual', 'w2treeview_group', 'w2treeview_node', 'w2treeview_virtual_main_div', 'treeview_virtual_node', 'treeview_label' 등의 클래스가 추가됩니다."
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);

    // comp 초기 생성
    scwin.comp_init();
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    let properties = {        
        renderType : con_renderType.getText()
    }

    let cList = $c.gcm.createCList(properties)

    // comp 생성 함수 호출    
    $c.gcm.createBasicTreeView(cList);    
}



scwin.btn_getRenderType_onclick = function (e) {
    let rtn = '';
    let renderType = con_renderType.getText();

    if (renderType == "virtual") {       
        rtn = target1.render.tagName;
        wf_body_bottom.getObj("scwin").setReturnValue("Main tagName : " + rtn);

        rtn = target1.render.className;
        wf_body_bottom.getObj("scwin").setReturnValue("Main className : " + rtn);

        let divElements = document.querySelectorAll('div[id*="target1_node"]')

        if (divElements.length > 0) {
            for (var i =0; i < divElements.length; i++) {
                wf_body_bottom.getObj("scwin").setReturnValue("Item["+i+"] tagName : " + divElements[i].tagName);
                wf_body_bottom.getObj("scwin").setReturnValue("Item["+i+"] className : " + divElements[i].className);
            }
        }
    }
    else {
        rtn = target1.render.tagName;        
        wf_body_bottom.getObj("scwin").setReturnValue("Main tagName : " + rtn);

        rtn = target1.render.className;
        wf_body_bottom.getObj("scwin").setReturnValue("Main className : " + rtn);

        let tableElements = document.querySelectorAll('table[id*="target1_node"]')

        if (tableElements.length > 0) {
            for (var i =0; i < tableElements.length; i++) {
                wf_body_bottom.getObj("scwin").setReturnValue("Item["+i+"] tagName : " + tableElements[i].tagName);
                wf_body_bottom.getObj("scwin").setReturnValue("Item["+i+"] className : " + tableElements[i].className);
            }
        }
    } 
};
